import { SVGIcon } from '@progress/kendo-react-common';
import * as React from 'react';
/**
 * The props passed to a custom `headerTemplate` component for `AgentStep`-based components
 * (`Reasoning`, `ChainOfThought`, `ToolCall`).
 *
 * When a `headerTemplate` is provided, the component renders the custom component
 * instead of the default step header. All data the default header uses is forwarded.
 *
 * @hidden
 */
export interface AgentStepHeaderTemplateProps {
    /** The SVG icon displayed in the step header. */
    svgIcon?: SVGIcon;
    /** The primary label text. */
    label?: string;
    /** The secondary label text. */
    secondaryLabel?: string;
    /** Additional content rendered in the header content area, e.g. a status badge. */
    headerExtra?: React.ReactNode;
    /** The number of lines added. */
    linesAdded?: number;
    /** The number of lines removed. */
    linesRemoved?: number;
    /** Whether the step is completed. */
    completed?: boolean;
    /** Whether the step is currently expanded. */
    expanded?: boolean;
    /** Whether the step can be expanded/collapsed. */
    expandable?: boolean;
    /** Custom content rendered inside the header. */
    children?: React.ReactNode;
}
